"""Category 7: validator attacks generated by Claude (RT-G, A35). Threat model: docs/governance/red-team.md section 5.7.

The cases are committed JSON under tests/redteam/generated/ (written by `make redteam-generate`, manual, network, never CI).
This file only replays them: no model, no network, deterministic. Each case is a draft-shaped message with one attack in
it; the expected outcome is "rejected". A case the validator accepted is a finding: it fails here until the validator is
fixed (with a test first) or the case carries a `known_limitation` string, which makes it a strict xfail listed in
red-team.md section 10.
"""

from __future__ import annotations

import json
import re
from pathlib import Path

import pytest
from harness import Case, params

from app.ai.provider import DraftRequest
from app.ai.templates import SAMPLE_VALUES
from app.ai.validate import validate

GENERATED = Path(__file__).resolve().parent / "generated"


def _files() -> list[Path]:
    return sorted(GENERATED.glob("*.json"))


def _cases() -> list[Case]:
    out = []
    for path in _files():
        for c in json.loads(path.read_text(encoding="utf-8"))["cases"]:
            limitation = c.get("known_limitation")
            out.append(Case(c["id"], c["text"], "rejected", note=c["language"], display=c["text"],
                            xfail=limitation if limitation and limitation.startswith("known limitation") else None))
    return out


def _req(language: str) -> DraftRequest:
    s = SAMPLE_VALUES[language]
    return DraftRequest("result_notification", "whatsapp", language, s["owner_name"], "primary_care_owner", s["next_step"],
                        "colorectal_fit")


@pytest.mark.parametrize("case", params(_cases()))
def test_generated_attack_is_rejected(case, rt):
    res = validate(case.input, _req(case.note))
    rt.actual("accepted" if res.ok else "rejected: " + ",".join(res.reasons))
    assert not res.ok, f"{case.id} accepted"


def test_generated_files_are_well_formed_and_hold_no_secret():
    seen: set[str] = set()
    for path in _files():
        raw = path.read_text(encoding="utf-8")
        assert not re.search(r"sk-ant|api[_-]?key|authorization", raw, re.I), path.name
        for c in json.loads(raw)["cases"]:
            assert re.fullmatch(r"RT-G-\d{2}[EA]\.\d+", c["id"]) and c["id"] not in seen, c["id"]
            assert c["language"] in ("en", "ar") and c["text"].strip()
            seen.add(c["id"])
